@Finsupp.mem_span_image_iff_linearCombination : ∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Semiring R]
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {v : α → M} {s : Set α} {x : M},
  x ∈ Submodule.span R (v '' s) ↔ ∃ l ∈ Finsupp.supported R R s, (Finsupp.linearCombination R v) l = x

@Finsupp.linearCombination_apply : ∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Semiring R]
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {v : α → M} (l : α →₀ R),
